// Kuiper Belt Station - habitat capacity planner (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var pop=[120,8000,500000], self_=[55,88,99.5];
console.log("Kuiper Belt Station - life support math");
console.log("==================================================");
for(var m=0;m<3;m++){
  var o2=pop[m]*0.84, water=pop[m]*3.5, food=pop[m]*2.1;
  var resupply=(100-self_[m])/100;
  console.log("Mark "+(m+1)+": "+pop[m].toLocaleString()+" people at "+self_[m]+"% self-sufficiency");
  console.log("  daily: "+o2.toFixed(0)+" kg O2, "+water.toFixed(0)+" L water, "+food.toFixed(0)+" kg food");
  console.log("  annual resupply mass: "+(o2*365*resupply/1000).toFixed(0)+" t O2-equivalent");
}

